            if load + d <= capacity:
                rr.append(c)
                seen.add(c)
                load += d
        if rr:
            final_routes.append(rr)

    # Add any missed customers as singleton routes
    for c in customers:
        if c not in seen:
            final_routes.append([c])
            seen.add(c)

    return final_routes
